import {esc} from './weather-tools.js';
import {climateState,weatherPatch,skyWindow} from './climate-engine.js';
const $=s=>document.querySelector(s);
export function createEditorial(ctx){
 let adaptive=true,assets=null,assetUser='',loading=false,room=null,roomData=null,poll=0,roomBusy=false,request=0,roomDraft='',messageId=crypto.randomUUID(),sendBusy=false;
 try{adaptive=localStorage.getItem('ms-adaptive')!=='off'}catch{}
 function apply(){const state=climateState(ctx.get().weather);document.documentElement.dataset.climate=adaptive?state.mode:'quiet';document.documentElement.dataset.climateSurface=['community','stories','tendenze','studio','redazione','stanza'].includes(ctx.get().route)?'on':'off';return state}
 function banner(){const state=apply();return `<div class="climate-banner"><div><b>${esc(state.label)}</b><small>${state.known?'L’aspetto segue il meteo della località selezionata.':'In attesa di dati per adattare l’esperienza.'}</small></div><button data-adaptive aria-pressed="${adaptive}">${adaptive?'Meteo adattivo attivo':'Modalità neutra'}</button><a href="#studio">Apri Studio</a></div>`}
 function patch(){const p=weatherPatch(ctx.get().weather,ctx.get().place.name);return `<section class="patch-card"><span class="eyebrow">PATCH NOTES · BOLLETTINO CREATIVO</span><h2>${esc(p.title)}</h2><ul>${p.lines.map(l=>`<li>${esc(l)}</li>`).join('')}</ul><small>${esc(p.source)}</small><a href="#studio">Trasforma in una slide →</a></section>`}
 function drop(){const w=skyWindow(ctx.get().weather),label=w?.active?'La finestra di luce è aperta.':w?'Prossimo Sky-Drop':'Sky-Drop in attesa del meteo';return `<section class="sky-drop" id="sky-drop"><span class="eyebrow">SKY-DROP · LUCE DELLA SERA</span><h2>${label}</h2><p>${w?.active?Math.floor(w.remaining/60)+':'+String(w.remaining%60).padStart(2,'0')+' rimasti nella finestra creativa.':w?new Date(w.start).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' · ora del tuo dispositivo.':'Serve l’orario del tramonto della località scelta.'}</p><p>Una finestra di 5 minuti, 30 minuti prima del tramonto previsto. Luce e visibilità dipendono da nuvole e luogo. Nessun obbligo di uscire.</p><a href="#studio" class="button">${w?.active?'Fotografa il tuo cielo':'Prepara la tua edizione'}</a><small>Promemoria nell’app aperta. Le notifiche push non sono collegate.</small></section>`}
 function hub(){const state=apply(),name=ctx.get().me?.profile?.name||'La tua redazione';return `<section class="editorial-workspace"><div class="studio-heading"><div><span class="eyebrow">MEDIA BRAND · METEOSOCIAL</span><h1>${esc(name)}</h1></div><a class="button" href="#studio">＋ Crea un’edizione</a></div>${banner()}<div class="editorial-grid"><section class="brand-sheet"><span class="brand-monogram" aria-hidden="true">${esc(name.slice(0,2).toUpperCase())}</span><h2>Una firma. Il tuo punto di vista.</h2><p>Foto, video e bollettini formano la tua testata meteo.</p><a href="#profilo">Modifica il nome della redazione →</a>${ctx.get().me?`<a href="#persona:${ctx.get().me.id}">Apri la tua pagina pubblica →</a>`:''}<div class="editorial-rubrics"><a href="#meteo-play">Meteo Play · tech</a><a href="#meteo-cinema">Meteo Cinema · film</a></div></section>${patch()}${drop()}<section class="brand-sheet"><span class="eyebrow">ASSET DELLA REDAZIONE</span><h2>Firma Orbitale</h2><p>Un timbro circolare esclusivo nell’editor, sbloccabile con apprezzamenti da 10 persone distinte sui tuoi post.</p><strong class="asset-count">${assets?.people??'—'} / 10</strong><button data-unlock-graphic ${assets?.earned.includes('graphic_orbit')?'disabled':''}>${assets?.earned.includes('graphic_orbit')?'Sbloccato · disponibile nello Studio':'Sblocca la firma'}</button><p id="editorial-assets-status" role="status"></p><small>Conteggi reali; auto-reazioni escluse. Questa soglia non certifica la viralità.</small></section></div><section class="room-invitation"><div><h2>Storm Rooms</h2><p>Una conversazione temporanea per chi si trova vicino alla città durante un temporale stimato.</p></div><a class="button" href="#stanza">Verifica la tua zona</a></section></section>`}
 function roomPage(){return `<section class="storm-workspace"><div class="studio-heading"><div><span class="eyebrow">STORM ROOMS</span><h1>Stesso temporale. Stessa stanza.</h1></div><a href="#community">Community →</a></div><section class="room-entry"><h2>${room?.active?esc(room.city):'Entra dalla tua posizione'}</h2><p>La posizione del dispositivo viene letta una volta e arrotondata a circa 1 km prima di consultare Open-Meteo. Non viene pubblicata nella chat. Accesso di massimo 10 minuti, stanza di massimo 30 minuti.</p><button data-enter-room class="button">${room?.active?'Rinnova la presenza':'Verifica la posizione e il meteo'}</button><p id="room-status" role="status">${room&&!room.active?esc(room.reason):room?.active?'Aperta fino alle '+new Date(room.expires).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})+' · '+esc(room.source):'Serve il consenso GPS. Disponibile entro 20 km dalle 35 città del catalogo.'}</p><small>Presenza dichiarata dal browser, non certificata. Non è un canale di emergenza. Contribuisci da un luogo sicuro.</small></section>${room?.active?`<section class="room-conversation"><div id="room-messages" aria-label="Messaggi della stanza" aria-live="polite">${messages()}</div><form id="room-compose"><label class="field">Messaggio pubblico alla stanza<textarea id="room-text" maxlength="500" required>${esc(roomDraft)}</textarea></label><button class="button">Invia</button></form><p>La conversazione diventa inaccessibile alla scadenza. Segnalazioni al gestore disponibili, revisione non immediata.</p></section>`:''}</section>`}
 function messages(){return roomData?.messages.length?roomData.messages.map(m=>`<article class="room-message"><b>${esc(m.name)}</b><small>${new Date(m.created).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</small><p>${esc(m.text)}</p>${m.user===ctx.get().me?.id?`<button data-room-delete="${m.id}">Elimina</button>`:`<button data-room-flag="${m.id}">Segnala</button>`}</article>`).join(''):'<p>La conversazione può iniziare da te.</p>'}
 async function loadAssets(){const who=ctx.get().me?.id;if(!who||loading)return;loading=true;try{const d=await ctx.api('studio/assets');if(ctx.get().me?.id===who){assets=d;assetUser=who;if(ctx.get().route==='redazione')ctx.render()}}catch(e){if($('#editorial-assets-status'))$('#editorial-assets-status').textContent=e.message}finally{loading=false}}
 async function readRoom(){if(!room?.active||roomBusy||document.hidden)return;const id=room.id,token=request;roomBusy=true;try{const d=await ctx.api('studio/room?id='+encodeURIComponent(id));if(token!==request||room?.id!==id)return;roomData=d;if($('#room-messages')){$('#room-messages').innerHTML=messages();bindMessageActions()}}catch(e){if(token===request&&$('#room-status')){$('#room-status').textContent=e.message;if(Date.now()>=room.accessExpires){room.active=false;stop();ctx.render()}}}finally{roomBusy=false}}
 function stop(){clearInterval(poll);poll=0;request++}
 async function enter(){if(!ctx.get().me)return ctx.login();if(!navigator.geolocation)return ctx.toast('Posizione non disponibile nel browser.');if(roomBusy)return;roomBusy=true;const button=$('[data-enter-room]');button.disabled=true;$('#room-status').textContent='Attendo la posizione e consulto il modello meteo…';const token=++request;try{const p=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{timeout:12000,maximumAge:60000,enableHighAccuracy:false}));if(token!==request)return;const d=await ctx.api('studio/enter',{latitude:Math.round(p.coords.latitude*100)/100,longitude:Math.round(p.coords.longitude*100)/100,accuracy:p.coords.accuracy});if(token!==request)return;room=d;roomData=null;roomDraft='';messageId=crypto.randomUUID();roomBusy=false;ctx.render()}catch(e){if(token===request&&$('#room-status'))$('#room-status').textContent=e.message||'Posizione non disponibile o consenso negato.'}finally{roomBusy=false;button.disabled=false}}
 function bindMessageActions(){document.querySelectorAll('[data-room-delete]').forEach(b=>b.onclick=()=>ctx.modal('Elimina il tuo messaggio','<p>Il messaggio non sarà più visibile nella stanza.</p>',async()=>{await ctx.api('studio/delete-message',{room:room.id,id:b.dataset.roomDelete});await readRoom()}));document.querySelectorAll('[data-room-flag]').forEach(b=>b.onclick=()=>ctx.modal('Segnala il messaggio','<label class="field">Motivo<input id="room-reason" required maxlength="200"></label>',async()=>{await ctx.api('studio/flag-message',{room:room.id,id:b.dataset.roomFlag,reason:$('#room-reason').value});ctx.toast('Segnalazione registrata per il gestore.')}))}
 function bind(){apply();document.querySelectorAll('[data-adaptive]').forEach(b=>b.onclick=()=>{adaptive=!adaptive;try{localStorage.setItem('ms-adaptive',adaptive?'on':'off')}catch{}ctx.render()});if(ctx.get().me?.id!==assetUser){assets=null;assetUser='';if(['redazione','studio'].includes(ctx.get().route))loadAssets()}$('[data-unlock-graphic]')?.addEventListener('click',async()=>{if(!ctx.get().me)return ctx.login();try{await ctx.api('studio/unlock',{});assetUser='';await loadAssets();ctx.toast('Firma Orbitale sbloccata nello Studio.')}catch(e){$('#editorial-assets-status').textContent=e.message}});if(ctx.get().route==='stanza'){$('[data-enter-room]').onclick=enter;$('#room-text')?.addEventListener('input',e=>roomDraft=e.target.value);$('#room-compose')?.addEventListener('submit',async e=>{e.preventDefault();if(sendBusy)return;sendBusy=true;const button=e.target.querySelector('button');button.disabled=true;try{await ctx.api('studio/message',{room:room.id,id:messageId,text:roomDraft});messageId=crypto.randomUUID();roomDraft='';if($('#room-text'))$('#room-text').value='';await readRoom()}catch(e){ctx.toast(e.message)}finally{sendBusy=false;button.disabled=false}});bindMessageActions();if(room?.active&&!poll){readRoom();poll=setInterval(readRoom,15000)}}}
 setInterval(()=>{if(!document.hidden&&$('#sky-drop'))$('#sky-drop').outerHTML=drop()},30000);
 return {hub,roomPage,patch,banner,apply,bind,adaptive:()=>adaptive,hasOrbit:()=>assets?.earned.includes('graphic_orbit')||false,dispose(next){if(next!=='stanza')stop()},refresh(){apply();if(['redazione'].includes(ctx.get().route))ctx.render()}};
}
